334	            .insert_source(listening_socket, move |client_stream, _, state| {
335	                // Inside the callback, you should insert the client into the display.
336	                //
337	                // You may also associate some data with the client when inserting the client.
338	                if let Err(error) = state
339	                    .display_handle
340	                    .insert_client(client_stream, Arc::new(ClientState::default()))
341	                {
342	                    tracing::warn!(%error, "client admission failed");
343	                }
344	            })
345	            .map_err(|e| std::io::Error::other(e.to_string()))?;
346	
347	        // Share display ownership with a one-shot wake path. An explicit
348	        // disconnect must drain backend destructors without peer traffic.
349	        let dispatcher = calloop::Dispatcher::new(
350	            Generic::new(display, Interest::READ, Mode::Level),
351	            |_, display, state: &mut Self| {
352	                // SAFETY: the registered display remains owned by the dispatcher.
353	                state.dispatch_wayland(unsafe { display.get_mut() });
354	                Ok(PostAction::Continue)
355	            },
356	        );
357	        loop_handle
358	            .register_dispatcher(dispatcher.clone())
359	            .map_err(|e| std::io::Error::other(e.to_string()))?;
360	        let (ping, source) = smithay::reexports::calloop::ping::make_ping()?;
361	        loop_handle
362	            .insert_source(source, move |(), _, state| {
363	                let mut display = dispatcher.as_source_mut();
364	                // SAFETY: the ping callback only borrows the owned display; calloop
365	                // does not run its readable callback concurrently.
366	                let display = unsafe { display.get_mut() };
367	                for client in std::mem::take(&mut state.pending_client_disconnects) {
368	                    // dispatch_all_clients only cleans up after readable events
369	                    // in the Rust backend. Single-client dispatch always drains
370	                    // retired objects, including an entirely silent peer.
371	                    match display.backend().dispatch_single_client(state, client) {
372	                        Ok(requests) => state.stats.wayland_requests += requests as u64,
373	                        Err(error) => tracing::debug!(%error, "retired client dispatch"),
374	                    }
375	                }
376	            })
377	            .map_err(|e| std::io::Error::other(e.to_string()))?;
378	
379	        Ok((socket_name, ping))
380	    }
