382	    fn dispatch_wayland(&mut self, display: &mut Display<Self>) {
383	        match display.dispatch_clients(self) {
384	            Ok(requests) => self.stats.wayland_requests += requests as u64,
385	            Err(error) => self.fail(format!("Wayland dispatch failed: {error}")),
386	        }
387	    }
